void DelayEditor::timerCallback(){const auto s=p.settings();for(int i=0;i<2;++i){auto syncOn=s.taps[(std::size_t)i].sync;knobs[(std::size_t)i+3].setVisible(!syncOn);notes[(std::size_t)i].setVisible(syncOn);rhythms[(std::size_t)i].setVisible(syncOn);multipliers[(std::size_t)i].setEnabled(syncOn);}bpm.setEnabled(!p.tempoAvailable);bpmLabel.setText(p.tempoAvailable?"CUBASE TEMPO  ·  "+String(p.displayedBpm.load(),2)+" BPM":"NO HOST TEMPO  ·  use fallback BPM",dontSendNotification);String info=p.limited?"Delay limited to 10 seconds":"Drag handles: time / pan";status.setText(info,dontSendNotification);graph.repaint();}
Point<float> DelayEditor::Graph::point(int i)const{auto s=editor.p.settings();const auto& t=s.taps[(std::size_t)i];float x=t.sync?float(t.multiplier-1)/9.f:float(t.milliseconds/9999.);return {24+x*(getWidth()-48),24+float((t.pan+1)*.5)*(getHeight()-48)};}
void DelayEditor::Graph::paint(Graphics& g){g.setColour(navy);g.fillRoundedRectangle(getLocalBounds().toFloat(),8);g.setColour(Colour(0xff284a60));for(int i=1;i<10;++i)g.drawVerticalLine(24+i*(getWidth()-48)/9,20.f,float(getHeight()-20));g.drawHorizontalLine(getHeight()/2,20.f,float(getWidth()-20));text(g,"L",{7,8,15,20},10,muted);text(g,"R",{7,getHeight()-28,15,20},10,muted);text(g,"TIME",{getWidth()-54,getHeight()-23,42,18},10,muted);
 for(int i=1;i>=0;--i){auto dot=point(i);auto colour=i?Colour(0xff4ba6d6):Colour(0xffa6eef1);g.setColour(colour.withAlpha(.25f));g.drawLine(24,dot.y,dot.x,dot.y,2);g.setColour(colour);g.fillEllipse(dot.x-7,dot.y-7,14,14);text(g,String(i+1),{int(dot.x)-4,int(dot.y)+(dot.y<40?10:-26),22,18},12,colour);}
}
void DelayEditor::Graph::mouseDown(const MouseEvent& e){active=e.position.getDistanceFrom(point(0))<=e.position.getDistanceFrom(point(1))?0:1;auto s=editor.p.settings();horizontal=(s.taps[(std::size_t)active].sync?"mult":"time")+String(active+1);editor.p.state.getParameter(horizontal)->beginChangeGesture();editor.p.state.getParameter("pan"+String(active+1))->beginChangeGesture();mouseDrag(e);}
void DelayEditor::Graph::mouseDrag(const MouseEvent& e){if(active<0)return;auto x=std::clamp((e.position.x-24)/(getWidth()-48),0.f,1.f),y=std::clamp((e.position.y-24)/(getHeight()-48),0.f,1.f);auto* h=editor.p.state.getParameter(horizontal);h->setValueNotifyingHost(h->convertTo0to1(horizontal.startsWith("mult")?float(std::lround(1+x*9)):x*9999));auto* pan=editor.p.state.getParameter("pan"+String(active+1));pan->setValueNotifyingHost(pan->convertTo0to1(y*200-100));repaint();}
void DelayEditor::Graph::mouseUp(const MouseEvent&){if(active>=0){editor.p.state.getParameter(horizontal)->endChangeGesture();editor.p.state.getParameter("pan"+String(active+1))->endChangeGesture();active=-1;}}
